import numpy as np

def add_patch(images, corner='tl', patch_type='white', patch_size=3):
    """Add patch to images. corner: 'tl', 'tr', 'bl', 'br'. patch_type: 'white', 'checkerboard', 'noise'"""
    imgs = images.copy()
    n, c, h, w = imgs.shape
    pad = 1  # 1 pixel in from corner

    for i in range(n):
        if corner == 'tl':
            y, x = pad, pad
        elif corner == 'tr':
            y, x = pad, w - pad - patch_size
        elif corner == 'bl':
            y, x = h - pad - patch_size, pad
        elif corner == 'br':
            y, x = h - pad - patch_size, w - pad - patch_size

        if patch_type == 'white':
            patch = np.ones((c, patch_size, patch_size), dtype=np.uint8) * 255
        elif patch_type == 'checkerboard':
            patch = np.zeros((c, patch_size, patch_size), dtype=np.uint8)
            for py in range(patch_size):
                for px in range(patch_size):
                    if (py + px) % 2 == 0:
                        patch[:, py, px] = 255
        elif patch_type == 'noise':
            patch = np.random.randint(0, 2, (c, patch_size, patch_size), dtype=np.uint8) * 255

        imgs[i, :, y:y+patch_size, x:x+patch_size] = patch
    return imgs

